(()=>{
 const bundle=JSON.parse(document.getElementById('report-data').textContent),counts=[...new Set(bundle.checkpoints.map(row=>row.body.count))].sort((a,b)=>a-b),selected=new Set(),panel=document.createElement('section');panel.className='report-card';panel.setAttribute('aria-label','Choose signed record counts');const title=document.createElement('h2');title.textContent='Keep every claim at chosen counts';panel.append(title);const status=document.createElement('p');status.setAttribute('role','status');const save=document.createElement('button');save.type='button';save.textContent='Download chosen signed bundle';
 const refresh=()=>{const claims=bundle.checkpoints.filter(row=>selected.has(row.body.count));save.disabled=!selected.size;status.textContent=selected.size+' explicit count(s), '+claims.length+' original signed claim(s), including all supplied same-count conflicts. No import or history check.';};
 for(const count of counts){const label=document.createElement('label'),box=document.createElement('input');box.type='checkbox';const claims=bundle.checkpoints.filter(row=>row.body.count===count);label.append(box,document.createTextNode('Choose signed count '+count+' ('+claims.length+' claim'+(claims.length===1?'':'s')+')'));panel.append(label);box.addEventListener('input',()=>{if(box.checked)selected.add(count);else selected.delete(count);refresh();});}
 save.addEventListener('click',()=>{if(!selected.size)return;const value={...bundle,checkpoints:bundle.checkpoints.filter(row=>selected.has(row.body.count))},blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});if(blob.size>8*1024*1024)return status.textContent='Bundle exceeds8 MiB. Nothing downloaded.';const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='chosen-signed-claims.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Downloaded original chosen claims in supplied order, preserving every conflicting head at each count. Container is unsigned; separately verify/import with your independent public key. No custody, ancestry or completeness proof.';});panel.append(save,status);document.querySelector('.filters').after(panel);refresh();
})();
